#!/bin/sh
# Run after ac50 exits, while the raw MIDI control-surface device is available.
card=$(sed -n 's/^ *\([0-9][0-9]*\) \[Surface *\].*/\1/p' /proc/asound/cards | head -n 1)
[ -n "$card" ] || exit 1
device="/dev/snd/midiC${card}D0"
[ -c "$device" ] || exit 1
printf '\360\107\177\134\145\000\004\000\000\000\000\367\360\107\177\134\145\000\004\001\000\000\000\367\360\107\177\134\145\000\004\002\000\000\000\367\360\107\177\134\145\000\004\003\000\000\000\367\360\107\177\134\145\000\004\004\000\000\000\367\360\107\177\134\145\000\004\005\000\000\000\367\360\107\177\134\145\000\004\006\000\000\000\367\360\107\177\134\145\000\004\007\000\000\000\367\360\107\177\134\145\000\004\010\000\000\000\367\360\107\177\134\145\000\004\011\000\000\000\367\360\107\177\134\145\000\004\012\000\000\000\367\360\107\177\134\145\000\004\013\000\000\000\367\360\107\177\134\145\000\004\014\000\000\000\367\360\107\177\134\145\000\004\015\000\000\000\367\360\107\177\134\145\000\004\016\000\000\000\367\360\107\177\134\145\000\004\017\000\000\000\367' > "$device"
